window.EXAMPLES=[{"title": "Ejercicio 1 · Densidad e identificación de fluidos", "block": "Densidad e identificación de fluidos", "question": "Una botella vacía tiene una masa de 120 g. Llena con 500 mL de un líquido, la balanza indica 515 g. Calcula la densidad en kg/m<span class=\"math\" data-tex=\"^3\"></span> e identifica el líquido de la tabla.", "steps": [{"title": "Interpretar los datos", "html": "<p>Obtén la masa neta y el volumen ocupado.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La densidad es la razón entre ambas magnitudes; compara con la tabla.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>La masa del líquido es <span class=\"math\" data-tex=\"515-120=395\"></span> g; no se utiliza la masa del recipiente. <span class=\"math\" data-tex=\"\\rho=395/500=0.790\"></span> g/mL <span class=\"math\" data-tex=\"=790\"></span> kg/m<span class=\"math\" data-tex=\"^3\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"790\\ \\mathrm{kg/m^3}\"></span>; etanol de referencia.</p>"}], "figure": ""}, {"title": "Ejercicio 2 · Densidad e identificación de fluidos", "block": "Densidad e identificación de fluidos", "question": "Un recipiente rectangular tiene base interior de 10 cm por 5 cm. El líquido alcanza una altura de 8 cm y tiene masa neta de 344 g. Calcula su densidad e identifica el fluido.", "steps": [{"title": "Interpretar los datos", "html": "<p>Obtén la masa neta y el volumen ocupado.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La densidad es la razón entre ambas magnitudes; compara con la tabla.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"V=(10)(5)(8)=400\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"\\rho=344/400=0.860\"></span> g/cm<span class=\"math\" data-tex=\"^3\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"860\\ \\mathrm{kg/m^3}\"></span>; aceite de referencia.</p>"}], "figure": ""}, {"title": "Ejercicio 3 · Densidad e identificación de fluidos", "block": "Densidad e identificación de fluidos", "question": "Un recipiente cilíndrico vacío tiene masa de 100 g. Su diámetro interior es de 10 cm y el líquido alcanza una altura de 8 cm. La masa total es 728 g. Calcula la densidad e identifica el líquido.", "steps": [{"title": "Interpretar los datos", "html": "<p>Obtén la masa neta y el volumen ocupado.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La densidad es la razón entre ambas magnitudes; compara con la tabla.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>El radio es <span class=\"math\" data-tex=\"10/2=5\"></span> cm. <span class=\"math\" data-tex=\"V=\\pi r^2h=(3.14)(5)^2(8)=628\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. La masa líquida es <span class=\"math\" data-tex=\"728-100=628\"></span> g; <span class=\"math\" data-tex=\"\\rho=628/628=1.000\"></span> g/cm<span class=\"math\" data-tex=\"^3\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"1000\\ \\mathrm{kg/m^3}\"></span>; agua.</p>"}], "figure": ""}, {"title": "Ejercicio 4 · Densidad e identificación de fluidos", "block": "Densidad e identificación de fluidos", "question": "Un recipiente con líquido registra inicialmente 280 g de masa total y 15 mL de volumen. Al añadir más del mismo líquido, registra 821.6 g y 55 mL. Calcula la densidad de la porción añadida e identifica el fluido de la tabla.", "steps": [{"title": "Interpretar los datos", "html": "<p>Obtén la masa neta y el volumen ocupado.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La densidad es la razón entre ambas magnitudes; compara con la tabla.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>El recipiente y la porción inicial se cancelan al restar: <span class=\"math\" data-tex=\"\\Delta m=821.6-280=541.6\"></span> g y <span class=\"math\" data-tex=\"\\Delta V=55-15=40\"></span> mL. <span class=\"math\" data-tex=\"\\rho=541.6/40=13.54\"></span> g/mL.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"13 540\\ \\mathrm{kg/m^3}\"></span>; mercurio.</p>"}], "figure": ""}, {"title": "Ejercicio 5 · Densidad e identificación de fluidos", "block": "Densidad e identificación de fluidos", "question": "Un recipiente vacío tiene masa de 55 g. Con 200 mL de un líquido, su masa total es de 215 g. Calcula la densidad del líquido en kg/m<span class=\"math\" data-tex=\"^3\"></span> e identifícalo en la tabla.", "steps": [{"title": "Interpretar los datos", "html": "<p>Obtén la masa neta y el volumen ocupado.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La densidad es la razón entre ambas magnitudes; compara con la tabla.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>La masa del líquido es <span class=\"math\" data-tex=\"215-55=160\"></span> g. Su densidad es <span class=\"math\" data-tex=\"\\rho=160/200=0.800\"></span> g/mL <span class=\"math\" data-tex=\"=800\"></span> kg/m<span class=\"math\" data-tex=\"^3\"></span>, que coincide exactamente con el queroseno de la tabla.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"800\\ \\mathrm{kg/m^3}\"></span>; queroseno.</p>"}], "figure": ""}, {"title": "Ejercicio 6 · Masa a partir de datos indirectos", "block": "Masa a partir de datos indirectos", "question": "Un acuario rectangular tiene base interior de 40 cm por 25 cm y el agua alcanza 30 cm de altura. El acuario vacío tiene masa de 3.50 kg. Calcula la masa total del acuario con agua.", "steps": [{"title": "Interpretar los datos", "html": "<p>Deduce el volumen real de sustancia.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Descuenta huecos, aplica el porcentaje de llenado y añade el recipiente solo al final si se pide.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"V=(40)(25)(30)=30 000\"></span> cm<span class=\"math\" data-tex=\"^3=0.0300\"></span> m<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"m_{\\rm agua}=(1000)(0.0300)=30.0\"></span> kg. <span class=\"math\" data-tex=\"m_{\\rm total}=30.0+3.50\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"33.50\\ \\mathrm{kg}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 7 · Masa a partir de datos indirectos", "block": "Masa a partir de datos indirectos", "question": "Un tubo de acero tiene radio exterior de 3 cm, radio interior de 2 cm y longitud de 10 cm. Usando la densidad del acero de la tabla, calcula la masa del tubo; los extremos están abiertos.", "steps": [{"title": "Interpretar los datos", "html": "<p>Deduce el volumen real de sustancia.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Descuenta huecos, aplica el porcentaje de llenado y añade el recipiente solo al final si se pide.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>El material ocupa la diferencia entre dos cilindros: <span class=\"math\" data-tex=\"V=\\pi(R^2-r^2)L=(3.14)(9-4)(10)=157\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"\\rho_{\\rm acero}=7.80\"></span> g/cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"m=(7.80)(157)=1224.6\"></span> g.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"1.2246\\ \\mathrm{kg}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 8 · Masa a partir de datos indirectos", "block": "Masa a partir de datos indirectos", "question": "Un recipiente cilíndrico tiene diámetro interior de 20 cm, altura interior de 30 cm y masa vacía de 1.20 kg. Se llena con aceite hasta tres cuartas partes de su altura. Calcula la masa total.", "steps": [{"title": "Interpretar los datos", "html": "<p>Deduce el volumen real de sustancia.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Descuenta huecos, aplica el porcentaje de llenado y añade el recipiente solo al final si se pide.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"r=10\"></span> cm, <span class=\"math\" data-tex=\"h=(3/4)(30)=22.5\"></span> cm. <span class=\"math\" data-tex=\"V=(3.14)(10)^2(22.5)=7065\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"m_L=(0.860)(7065)=6075.9\"></span> g. Se suma 1.20 kg del recipiente.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"7.2759\\ \\mathrm{kg}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 9 · Masa a partir de datos indirectos", "block": "Masa a partir de datos indirectos", "question": "Un tanque cúbico de arista interior de 40 cm contiene un combustible de <span class=\"math\" data-tex=\"sg=0.79\"></span> hasta el 60% de su capacidad. Calcula la masa de combustible.", "steps": [{"title": "Interpretar los datos", "html": "<p>Deduce el volumen real de sustancia.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Descuenta huecos, aplica el porcentaje de llenado y añade el recipiente solo al final si se pide.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"\\rho=(0.79)(1000)=790\"></span> kg/m<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"V=0.60(0.40)^3=0.0384\"></span> m<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"m=(790)(0.0384)\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"30.336\\ \\mathrm{kg}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 10 · Masa a partir de datos indirectos", "block": "Masa a partir de datos indirectos", "question": "Un recipiente vacío tiene masa de 1.50 kg y, lleno de agua hasta el borde, tiene masa de 11.50 kg. Se vacía y se llena con aceite hasta el 80% de su capacidad. Calcula la masa total del recipiente con aceite.", "steps": [{"title": "Interpretar los datos", "html": "<p>Deduce el volumen real de sustancia.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Descuenta huecos, aplica el porcentaje de llenado y añade el recipiente solo al final si se pide.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>La capacidad se deduce con el agua: <span class=\"math\" data-tex=\"m_{\\rm agua}=10.00\"></span> kg y <span class=\"math\" data-tex=\"V_{\\rm cap}=10/1000=0.0100\"></span> m<span class=\"math\" data-tex=\"^3\"></span>. El aceite ocupa <span class=\"math\" data-tex=\"0.80(0.0100)=0.00800\"></span> m<span class=\"math\" data-tex=\"^3\"></span>; su masa es <span class=\"math\" data-tex=\"860(0.00800)=6.88\"></span> kg. Se suma la masa del recipiente.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"8.38\\ \\mathrm{kg}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 11 · Volumen y dimensiones geométricas", "block": "Volumen y dimensiones geométricas", "question": "Una botella vacía tiene masa de 180 g. Llena con etanol, tiene masa total de 1365 g. Calcula el volumen de etanol en litros.", "steps": [{"title": "Interpretar los datos", "html": "<p>Relaciona masa neta y densidad para deducir V.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Si piden una dimensión, utiliza después la fórmula geométrica apropiada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"m_L=1365-180=1185\"></span> g; <span class=\"math\" data-tex=\"\\rho_{\\rm etanol}=0.790\"></span> g/mL. <span class=\"math\" data-tex=\"V=1185/0.790=1500\"></span> mL.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"1.50\\ \\mathrm{L}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 12 · Volumen y dimensiones geométricas", "block": "Volumen y dimensiones geométricas", "question": "Un cilindro macizo de aluminio tiene masa de 1.35648 kg y altura de 10 cm. Determina su volumen en cm<span class=\"math\" data-tex=\"^3\"></span> y su radio en cm.", "steps": [{"title": "Interpretar los datos", "html": "<p>Relaciona masa neta y densidad para deducir V.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Si piden una dimensión, utiliza después la fórmula geométrica apropiada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"m=1356.48\"></span> g y <span class=\"math\" data-tex=\"\\rho=2.70\"></span> g/cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"V=1356.48/2.70=502.4\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"r=\\sqrt{V/(\\pi h)}=\\sqrt{502.4/(3.14\\cdot10)}=4\"></span> cm.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"V=502.4\\ \\mathrm{cm^3}\"></span>; <span class=\"math\" data-tex=\"r=4.00\\ \\mathrm{cm}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 13 · Volumen y dimensiones geométricas", "block": "Volumen y dimensiones geométricas", "question": "Un recipiente rectangular tiene base interior de 30 cm por 20 cm. Contiene 10.32 kg de aceite. Calcula el volumen del aceite en litros y la altura que alcanza en cm.", "steps": [{"title": "Interpretar los datos", "html": "<p>Relaciona masa neta y densidad para deducir V.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Si piden una dimensión, utiliza después la fórmula geométrica apropiada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"V=10.32/860=0.0120\"></span> m<span class=\"math\" data-tex=\"^3=12 000\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"h=V/A=12 000/(30\\cdot20)=20\"></span> cm.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"V=12.0\\ \\mathrm{L}\"></span>; <span class=\"math\" data-tex=\"h=20.0\\ \\mathrm{cm}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 14 · Volumen y dimensiones geométricas", "block": "Volumen y dimensiones geométricas", "question": "Una pieza de aluminio, con una cavidad interior vacía, tiene dimensiones exteriores de 12 cm por 10 cm por 8 cm y masa de 2.16 kg. Calcula el volumen de la cavidad en cm<span class=\"math\" data-tex=\"^3\"></span>.", "steps": [{"title": "Interpretar los datos", "html": "<p>Relaciona masa neta y densidad para deducir V.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Si piden una dimensión, utiliza después la fórmula geométrica apropiada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"V_{\\rm exterior}=12(10)(8)=960\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. El aluminio ocupa <span class=\"math\" data-tex=\"V_{\\rm material}=2160/2.70=800\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"V_{\\rm cavidad}=960-800\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"160\\ \\mathrm{cm^3}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 15 · Volumen y dimensiones geométricas", "block": "Volumen y dimensiones geométricas", "question": "Una esfera se introduce por completo en una probeta cilíndrica de radio interior de 5 cm. El nivel del agua sube 1.44 cm, sin derramarse. Determina el volumen de la esfera y su radio.", "steps": [{"title": "Interpretar los datos", "html": "<p>Relaciona masa neta y densidad para deducir V.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Si piden una dimensión, utiliza después la fórmula geométrica apropiada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>El volumen desplazado es <span class=\"math\" data-tex=\"V=\\pi r_{\\rm probeta}^2\\Delta h=(3.14)(5)^2(1.44)=113.04\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. Para la esfera, <span class=\"math\" data-tex=\"R=\\sqrt[3]{3V/(4\\pi)}=\\sqrt[3]{27}=3\"></span> cm.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"V=113.04\\ \\mathrm{cm^3}\"></span>; <span class=\"math\" data-tex=\"R=3\\ \\mathrm{cm}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 16 · Gravedad específica e interpretación", "block": "Gravedad específica e interpretación", "question": "Una probeta tiene masa vacía de 65 g. Con 150 mL de un líquido su masa total es de 185 g. Calcula la gravedad específica e identifica el líquido de la tabla.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la densidad del material o la relación que permite deducirla.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La referencia de sg es el agua: 1000 kg/m³. El resultado no tiene unidades.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"m_L=185-65=120\"></span> g; <span class=\"math\" data-tex=\"\\rho=120/150=0.800\"></span> g/mL <span class=\"math\" data-tex=\"=800\"></span> kg/m<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"sg=800/1000\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"sg=0.80\"></span>; queroseno.</p>"}], "figure": ""}, {"title": "Ejercicio 17 · Gravedad específica e interpretación", "block": "Gravedad específica e interpretación", "question": "Un frasco vacío tiene masa de 75 g. Lleno de agua tiene masa total de 325 g; lleno hasta el mismo nivel con otro líquido tiene masa total de 390 g. Calcula la gravedad específica del líquido e identifícalo.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la densidad del material o la relación que permite deducirla.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La referencia de sg es el agua: 1000 kg/m³. El resultado no tiene unidades.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>Para el mismo volumen, <span class=\"math\" data-tex=\"sg=m_L/m_{\\rm agua}\"></span>. <span class=\"math\" data-tex=\"m_L=390-75=315\"></span> g y <span class=\"math\" data-tex=\"m_{\\rm agua}=325-75=250\"></span> g. <span class=\"math\" data-tex=\"sg=315/250=1.26\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"sg=1.26\"></span>; glicerina.</p>"}], "figure": ""}, {"title": "Ejercicio 18 · Gravedad específica e interpretación", "block": "Gravedad específica e interpretación", "question": "Un líquido ocupa un cilindro de diámetro interior de 4 cm hasta una altura de 10 cm. La masa neta del líquido es de 108.016 g. Calcula su gravedad específica e identifica el fluido.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la densidad del material o la relación que permite deducirla.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La referencia de sg es el agua: 1000 kg/m³. El resultado no tiene unidades.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"r=2\"></span> cm. <span class=\"math\" data-tex=\"V=(3.14)(2)^2(10)=125.6\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"\\rho=108.016/125.6=0.860\"></span> g/cm<span class=\"math\" data-tex=\"^3\"></span>; <span class=\"math\" data-tex=\"sg=0.860/1.000\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"sg=0.86\"></span>; aceite de referencia.</p>"}], "figure": ""}, {"title": "Ejercicio 19 · Gravedad específica e interpretación", "block": "Gravedad específica e interpretación", "question": "Un bloque homogéneo flota en agua con el 64.5% de su volumen sumergido. Calcula su gravedad específica y el porcentaje de volumen que quedará sumergido al flotar en el aceite de la tabla.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la densidad del material o la relación que permite deducirla.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La referencia de sg es el agua: 1000 kg/m³. El resultado no tiene unidades.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>En agua, <span class=\"math\" data-tex=\"sg_c=V_s/V=0.645\"></span> y <span class=\"math\" data-tex=\"\\rho_c=(0.645)(1000)=645\"></span> kg/m<span class=\"math\" data-tex=\"^3\"></span>. En aceite, <span class=\"math\" data-tex=\"V_s/V=645/860=0.75\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"sg=0.645\"></span>; 75% sumergido en aceite.</p>"}], "figure": ""}, {"title": "Ejercicio 20 · Gravedad específica e interpretación", "block": "Gravedad específica e interpretación", "question": "Un depósito abierto contiene un líquido hasta 50 cm de altura. Un sensor al fondo indica una presión manométrica de 6.1803 kPa. Calcula la gravedad específica e identifica el líquido.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la densidad del material o la relación que permite deducirla.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>La referencia de sg es el agua: 1000 kg/m³. El resultado no tiene unidades.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"p=6180.3\"></span> Pa y <span class=\"math\" data-tex=\"h=0.50\"></span> m. De <span class=\"math\" data-tex=\"p=\\rho gh\"></span>, <span class=\"math\" data-tex=\"\\rho=6180.3/(9.81\\cdot0.50)=1260\"></span> kg/m<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"sg=1260/1000\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"sg=1.26\"></span>; glicerina.</p>"}], "figure": ""}, {"title": "Ejercicio 21 · Principio de Pascal y mecanismos", "block": "Principio de Pascal y mecanismos", "question": "Un elevador hidráulico tiene pistones de diámetros 3 cm y 15 cm. Debe sostener un automóvil de 1200 kg. Calcula la fuerza mínima aplicada al pistón pequeño.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja las fuerzas de cada pistón y calcula sus áreas.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa Pascal. Si hay palanca, equilibra sus momentos antes; si hay recorridos, conserva el volumen.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>La carga ejerce <span class=\"math\" data-tex=\"F_2=mg=(1200)(9.81)=11 772\"></span> N. La razón de áreas es <span class=\"math\" data-tex=\"(3/15)^2=1/25\"></span>. <span class=\"math\" data-tex=\"F_1=11 772/25\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"470.88\\ \\mathrm{N}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 22 · Principio de Pascal y mecanismos", "block": "Principio de Pascal y mecanismos", "question": "Se aplican 180 N a un pistón de diámetro 2 cm. Se necesita una fuerza de salida de 4500 N. Determina el diámetro mínimo del pistón grande.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja las fuerzas de cada pistón y calcula sus áreas.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa Pascal. Si hay palanca, equilibra sus momentos antes; si hay recorridos, conserva el volumen.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"F_2/F_1=(D_2/D_1)^2\"></span>. Así, <span class=\"math\" data-tex=\"D_2=D_1\\sqrt{F_2/F_1}=2\\sqrt{4500/180}=2\\sqrt{25}\"></span> cm.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"D_2=10\\ \\mathrm{cm}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 23 · Principio de Pascal y mecanismos", "block": "Principio de Pascal y mecanismos", "question": "Un elevador tiene pistones de diámetros 2 cm y 20 cm. Sobre el pistón pequeño se coloca una carga de 20 kg. La plataforma del pistón grande tiene masa de 150 kg. Calcula la masa máxima adicional que puede sostener el grande.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja las fuerzas de cada pistón y calcula sus áreas.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa Pascal. Si hay palanca, equilibra sus momentos antes; si hay recorridos, conserva el volumen.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>La fuerza de entrada es <span class=\"math\" data-tex=\"F_1=(20)(9.81)=196.2\"></span> N. <span class=\"math\" data-tex=\"F_2=196.2(20/2)^2=19 620\"></span> N. Esta fuerza sostiene plataforma y carga: <span class=\"math\" data-tex=\"m_{\\rm carga}=19 620/9.81-150=2000-150\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"1850\\ \\mathrm{kg}\"></span> de carga adicional.</p>"}], "figure": ""}, {"title": "Ejercicio 24 · Principio de Pascal y mecanismos", "block": "Principio de Pascal y mecanismos", "question": "Los pistones de una prensa tienen diámetros de 4 cm y 20 cm. Cada carrera completa hace bajar 30 cm al pistón pequeño. Una válvula permite acumular la elevación del grande entre carreras. Calcula cuánto sube por carrera y cuántas carreras completas se necesitan para elevarlo 18 cm.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja las fuerzas de cada pistón y calcula sus áreas.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa Pascal. Si hay palanca, equilibra sus momentos antes; si hay recorridos, conserva el volumen.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>La razón de áreas es <span class=\"math\" data-tex=\"(4/20)^2=1/25\"></span>. <span class=\"math\" data-tex=\"d_2=30/25=1.2\"></span> cm por carrera. <span class=\"math\" data-tex=\"N=18/1.2=15\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"1.20\\ \\mathrm{cm}\"></span> por carrera; 15 carreras.</p>"}], "figure": ""}, {"title": "Ejercicio 25 · Principio de Pascal y mecanismos", "block": "Principio de Pascal y mecanismos", "question": "Una palanca acciona el pistón pequeño de una prensa. Una pesa de 6 kg actúa a 40 cm del apoyo; el vástago del pistón actúa a 10 cm del mismo apoyo. Ambos brazos son perpendiculares a sus fuerzas. Las áreas de los pistones son 3 cm<span class=\"math\" data-tex=\"^2\"></span> y 150 cm<span class=\"math\" data-tex=\"^2\"></span>. Calcula la fuerza de salida y la masa máxima que puede sostener.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja las fuerzas de cada pistón y calcula sus áreas.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa Pascal. Si hay palanca, equilibra sus momentos antes; si hay recorridos, conserva el volumen.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>El peso de entrada es <span class=\"math\" data-tex=\"F=(6)(9.81)=58.86\"></span> N. Equilibrando momentos, <span class=\"math\" data-tex=\"F_1(10)=58.86(40)\"></span>, por lo que <span class=\"math\" data-tex=\"F_1=235.44\"></span> N. <span class=\"math\" data-tex=\"F_2=235.44(150/3)=11 772\"></span> N; <span class=\"math\" data-tex=\"m=11 772/9.81\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"F_2=11 772\\ \\mathrm{N}\"></span>; <span class=\"math\" data-tex=\"m=1200\\ \\mathrm{kg}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 26 · Manómetro en U", "block": "Manómetro en U", "question": "El manómetro contiene agua y mercurio. Calcula la presión manométrica en <span class=\"math\" data-tex=\"A\"></span>, en kPa.", "steps": [{"title": "Interpretar los datos", "html": "<p>Marca el inicio, el final, las interfaces y los desniveles verticales.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>En manométrica la rama abierta parte de cero. Baja: suma; sube: resta. Conserva el orden de la diferencia solicitada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>Desde la superficie abierta se bajan 120 mm en mercurio y se suben 150 mm en agua. <span class=\"math\" data-tex=\"p_A=(13 540)(9.81)(0.120)-(1000)(9.81)(0.150)=14 467.788\"></span> Pa.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"p_A=14.47\\ \\mathrm{kPa}\"></span></p>"}], "figure": "<svg class=\"figura\" viewBox=\"0 0 470 320\" role=\"img\"><defs><marker id=\"flecha\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"#1B3A6B\"/></marker></defs><path d=\"M145 85V250A55 55 0 0 0 255 250V65Q255 45 275 45H345\" fill=\"none\" stroke=\"#687784\" stroke-width=\"23\"/><path d=\"M145 85V250A55 55 0 0 0 255 250V65Q255 45 275 45H345\" fill=\"none\" stroke=\"white\" stroke-width=\"17\"/><path d=\"M145 130V250A55 55 0 0 0 255 250V200\" fill=\"none\" stroke=\"#a2a8b1\" stroke-width=\"15\"/><path d=\"M255 200V65Q255 45 275 45H345\" fill=\"none\" stroke=\"#8bcbe9\" stroke-width=\"15\"/><text x=\"356\" y=\"51\">A</text><text x=\"52\" y=\"73\">Abierto</text><path d=\"M100 130V200\" stroke=\"#1B3A6B\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"14\" y=\"165.0\">120 mm</text><path d=\"M385 45V200\" stroke=\"#1B3A6B\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"291\" y=\"122.5\">150 mm</text><text x=\"40\" y=\"315\">Mercurio, sg = 13.54</text><text x=\"279\" y=\"79\">Agua</text></svg>"}, {"title": "Ejercicio 27 · Manómetro en U", "block": "Manómetro en U", "question": "El manómetro contiene agua y mercurio. Calcula la presión manométrica en <span class=\"math\" data-tex=\"A\"></span>, en kPa.", "steps": [{"title": "Interpretar los datos", "html": "<p>Marca el inicio, el final, las interfaces y los desniveles verticales.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>En manométrica la rama abierta parte de cero. Baja: suma; sube: resta. Conserva el orden de la diferencia solicitada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>Desde la superficie abierta se suben 75 mm en mercurio y 100 mm en agua. <span class=\"math\" data-tex=\"p_A=-(13 540)(9.81)(0.075)-(1000)(9.81)(0.100)=-10 943.055\"></span> Pa.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"p_A=-10.94\\ \\mathrm{kPa}\"></span></p>"}], "figure": "<svg class=\"figura\" viewBox=\"0 0 470 320\" role=\"img\"><defs><marker id=\"flecha\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"#1B3A6B\"/></marker></defs><path d=\"M145 85V250A55 55 0 0 0 255 250V65Q255 45 275 45H345\" fill=\"none\" stroke=\"#687784\" stroke-width=\"23\"/><path d=\"M145 85V250A55 55 0 0 0 255 250V65Q255 45 275 45H345\" fill=\"none\" stroke=\"white\" stroke-width=\"17\"/><path d=\"M145 220V250A55 55 0 0 0 255 250V140\" fill=\"none\" stroke=\"#a2a8b1\" stroke-width=\"15\"/><path d=\"M255 140V65Q255 45 275 45H345\" fill=\"none\" stroke=\"#8bcbe9\" stroke-width=\"15\"/><text x=\"356\" y=\"51\">A</text><text x=\"52\" y=\"73\">Abierto</text><path d=\"M100 140V220\" stroke=\"#1B3A6B\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"14\" y=\"180.0\">75 mm</text><path d=\"M385 45V140\" stroke=\"#1B3A6B\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"291\" y=\"92.5\">100 mm</text><text x=\"40\" y=\"315\">Mercurio, sg = 13.54</text><text x=\"279\" y=\"79\">Agua</text></svg>"}, {"title": "Ejercicio 28 · Manómetro en U", "block": "Manómetro en U", "question": "En el manómetro diferencial hay agua, mercurio y aceite de <span class=\"math\" data-tex=\"sg=0.86\"></span>. Calcula <span class=\"math\" data-tex=\"p_A-p_B\"></span>, en kPa.", "steps": [{"title": "Interpretar los datos", "html": "<p>Marca el inicio, el final, las interfaces y los desniveles verticales.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>En manométrica la rama abierta parte de cero. Baja: suma; sube: resta. Conserva el orden de la diferencia solicitada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>De <span class=\"math\" data-tex=\"B\"></span> a <span class=\"math\" data-tex=\"A\"></span>: se baja 0.150 m en agua y <span class=\"math\" data-tex=\"0.900-0.150=0.750\"></span> m en mercurio; se sube 0.600 m en aceite. <span class=\"math\" data-tex=\"p_A-p_B=9.81[1000(0.150)+13 540(0.750)-860(0.600)]=96 030.09\"></span> Pa.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"p_A-p_B=96.03\\ \\mathrm{kPa}\"></span></p>"}], "figure": "<svg class=\"figura\" viewBox=\"0 0 470 320\" role=\"img\"><defs><marker id=\"flecha\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"#1B3A6B\"/></marker></defs><path d=\"M105 35.0H150Q170 35.0 170 55.0V270A47 47 0 0 0 264 270V131.66666666666666Q264 111.66666666666666 285 111.66666666666666H335\" fill=\"none\" stroke=\"#687784\" stroke-width=\"23\"/><path d=\"M105 35.0H150Q170 35.0 170 55.0V270A47 47 0 0 0 264 270V131.66666666666666Q264 111.66666666666666 285 111.66666666666666H335\" fill=\"none\" stroke=\"white\" stroke-width=\"17\"/><path d=\"M170 73.33333333333334V270A47 47 0 0 0 264 270V265\" fill=\"none\" stroke=\"#a2a8b1\" stroke-width=\"15\"/><path d=\"M105 35.0H150Q170 35.0 170 55.0V73.33333333333334\" fill=\"none\" stroke=\"#8bcbe9\" stroke-width=\"15\"/><path d=\"M264 265V131.66666666666666Q264 111.66666666666666 285 111.66666666666666H335\" fill=\"none\" stroke=\"#ead39a\" stroke-width=\"15\"/><text x=\"75\" y=\"41.0\">B</text><text x=\"344\" y=\"117.66666666666666\">A</text><path d=\"M55 35.0V265\" stroke=\"#202020\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"2\" y=\"150.0\">900</text><text x=\"2\" y=\"172.0\">mm</text><path d=\"M205 35.0V73.33333333333334\" stroke=\"#202020\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"220\" y=\"54.16666666666667\">150 mm</text><path d=\"M365 111.66666666666666V265\" stroke=\"#202020\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"375\" y=\"188.33333333333331\">600</text><text x=\"375\" y=\"210.33333333333331\">mm</text><text x=\"4\" y=\"312\">Hg: sg = 13.54</text><text x=\"290\" y=\"159.66666666666666\">Aceite</text></svg>"}, {"title": "Ejercicio 29 · Manómetro en U", "block": "Manómetro en U", "question": "El mercurio separa dos columnas de agua. Calcula <span class=\"math\" data-tex=\"p_A-p_B\"></span>, en kPa.", "steps": [{"title": "Interpretar los datos", "html": "<p>Marca el inicio, el final, las interfaces y los desniveles verticales.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>En manométrica la rama abierta parte de cero. Baja: suma; sube: resta. Conserva el orden de la diferencia solicitada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>De <span class=\"math\" data-tex=\"B\"></span> a <span class=\"math\" data-tex=\"A\"></span> se baja 0.100 m en agua y 0.600 m en mercurio; se sube 0.400 m en agua. <span class=\"math\" data-tex=\"p_A-p_B=9.81[1000(0.100)+13 540(0.600)-1000(0.400)]=76 753.44\"></span> Pa.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"p_A-p_B=76.75\\ \\mathrm{kPa}\"></span></p>"}], "figure": "<svg class=\"figura\" viewBox=\"0 0 470 320\" role=\"img\"><defs><marker id=\"flecha\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"#1B3A6B\"/></marker></defs><path d=\"M105 86.11111111111111H150Q170 86.11111111111111 170 106.11111111111111V270A47 47 0 0 0 264 270V182.77777777777777Q264 162.77777777777777 285 162.77777777777777H335\" fill=\"none\" stroke=\"#687784\" stroke-width=\"23\"/><path d=\"M105 86.11111111111111H150Q170 86.11111111111111 170 106.11111111111111V270A47 47 0 0 0 264 270V182.77777777777777Q264 162.77777777777777 285 162.77777777777777H335\" fill=\"none\" stroke=\"white\" stroke-width=\"17\"/><path d=\"M170 111.66666666666666V270A47 47 0 0 0 264 270V265\" fill=\"none\" stroke=\"#a2a8b1\" stroke-width=\"15\"/><path d=\"M105 86.11111111111111H150Q170 86.11111111111111 170 106.11111111111111V111.66666666666666\" fill=\"none\" stroke=\"#8bcbe9\" stroke-width=\"15\"/><path d=\"M264 265V182.77777777777777Q264 162.77777777777777 285 162.77777777777777H335\" fill=\"none\" stroke=\"#8bcbe9\" stroke-width=\"15\"/><text x=\"75\" y=\"92.11111111111111\">B</text><text x=\"344\" y=\"168.77777777777777\">A</text><path d=\"M55 86.11111111111111V265\" stroke=\"#202020\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"2\" y=\"175.55555555555554\">700</text><text x=\"2\" y=\"197.55555555555554\">mm</text><path d=\"M205 86.11111111111111V111.66666666666666\" stroke=\"#202020\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"220\" y=\"98.88888888888889\">100 mm</text><path d=\"M365 162.77777777777777V265\" stroke=\"#202020\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"375\" y=\"213.88888888888889\">400</text><text x=\"375\" y=\"235.88888888888889\">mm</text><text x=\"4\" y=\"312\">Hg: sg = 13.54</text><text x=\"290\" y=\"210.77777777777777\">Agua</text></svg>"}, {"title": "Ejercicio 30 · Manómetro en U", "block": "Manómetro en U", "question": "El líquido en ambas conexiones es aceite de <span class=\"math\" data-tex=\"sg=0.90\"></span>. Calcula <span class=\"math\" data-tex=\"p_B-p_A\"></span>, en kPa.", "steps": [{"title": "Interpretar los datos", "html": "<p>Marca el inicio, el final, las interfaces y los desniveles verticales.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>En manométrica la rama abierta parte de cero. Baja: suma; sube: resta. Conserva el orden de la diferencia solicitada.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>De <span class=\"math\" data-tex=\"B\"></span> a <span class=\"math\" data-tex=\"A\"></span>: bajar 0.200 m en aceite, bajar <span class=\"math\" data-tex=\"0.850-0.200=0.650\"></span> m en mercurio y subir 0.500 m en aceite. <span class=\"math\" data-tex=\"p_A-p_B=9.81[900(0.200)+13 540(0.650)-900(0.500)]=83 687.31\"></span> Pa. Se invierte la resta solicitada.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"p_B-p_A=-83.69\\ \\mathrm{kPa}\"></span></p>"}], "figure": "<svg class=\"figura\" viewBox=\"0 0 470 320\" role=\"img\"><defs><marker id=\"flecha\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"#1B3A6B\"/></marker></defs><path d=\"M105 47.77777777777774H150Q170 47.77777777777774 170 67.77777777777774V270A47 47 0 0 0 264 270V157.22222222222223Q264 137.22222222222223 285 137.22222222222223H335\" fill=\"none\" stroke=\"#687784\" stroke-width=\"23\"/><path d=\"M105 47.77777777777774H150Q170 47.77777777777774 170 67.77777777777774V270A47 47 0 0 0 264 270V157.22222222222223Q264 137.22222222222223 285 137.22222222222223H335\" fill=\"none\" stroke=\"white\" stroke-width=\"17\"/><path d=\"M170 98.88888888888889V270A47 47 0 0 0 264 270V265\" fill=\"none\" stroke=\"#a2a8b1\" stroke-width=\"15\"/><path d=\"M105 47.77777777777774H150Q170 47.77777777777774 170 67.77777777777774V98.88888888888889\" fill=\"none\" stroke=\"#ead39a\" stroke-width=\"15\"/><path d=\"M264 265V157.22222222222223Q264 137.22222222222223 285 137.22222222222223H335\" fill=\"none\" stroke=\"#ead39a\" stroke-width=\"15\"/><text x=\"75\" y=\"53.77777777777774\">B</text><text x=\"344\" y=\"143.22222222222223\">A</text><path d=\"M55 47.77777777777774V265\" stroke=\"#202020\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"2\" y=\"156.38888888888886\">850</text><text x=\"2\" y=\"178.38888888888886\">mm</text><path d=\"M205 47.77777777777774V98.88888888888889\" stroke=\"#202020\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"220\" y=\"73.33333333333331\">200 mm</text><path d=\"M365 137.22222222222223V265\" stroke=\"#202020\" marker-start=\"url(#flecha)\" marker-end=\"url(#flecha)\"/><text x=\"375\" y=\"201.11111111111111\">500</text><text x=\"375\" y=\"223.11111111111111\">mm</text><text x=\"4\" y=\"312\">Hg: sg = 13.54</text><text x=\"290\" y=\"185.22222222222223\">Aceite</text></svg>"}, {"title": "Ejercicio 31 · Empuje y equilibrio", "block": "Empuje y equilibrio", "question": "Un bloque de 10 cm por 8 cm por 5 cm tiene masa de 0.600 kg. Se mantiene completamente sumergido en agua mediante un dinamómetro sujeto desde arriba. Calcula el empuje y la lectura del instrumento.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja peso, empuje, tensión o apoyo según la situación.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Calcula el volumen desplazado y usa la densidad del fluido; después impón equilibrio o compara fuerzas.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"V=(10)(8)(5)=400\"></span> cm<span class=\"math\" data-tex=\"^3=0.000400\"></span> m<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"E=(1000)(9.81)(0.000400)=3.924\"></span> N. <span class=\"math\" data-tex=\"P=(0.600)(9.81)=5.886\"></span> N; <span class=\"math\" data-tex=\"T=P-E=1.962\"></span> N.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"E=3.924\\ \\mathrm{N}\"></span>; lectura <span class=\"math\" data-tex=\"=1.962\\ \\mathrm{N}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 32 · Empuje y equilibrio", "block": "Empuje y equilibrio", "question": "Un cubo de madera de arista 10 cm y densidad de 645 kg/m<span class=\"math\" data-tex=\"^3\"></span> flota con una cara horizontal en aceite. Calcula la altura sumergida y el empuje.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja peso, empuje, tensión o apoyo según la situación.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Calcula el volumen desplazado y usa la densidad del fluido; después impón equilibrio o compara fuerzas.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"V=(0.10)^3=0.001\"></span> m<span class=\"math\" data-tex=\"^3\"></span> y <span class=\"math\" data-tex=\"m=(645)(0.001)=0.645\"></span> kg. <span class=\"math\" data-tex=\"E=mg=(0.645)(9.81)=6.32745\"></span> N. <span class=\"math\" data-tex=\"h_s=(645/860)(10)=7.5\"></span> cm.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"h_s=7.5\\ \\mathrm{cm}\"></span>; <span class=\"math\" data-tex=\"E=6.32745\\ \\mathrm{N}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 33 · Empuje y equilibrio", "block": "Empuje y equilibrio", "question": "Un cilindro macizo de diámetro 4 cm y altura 10 cm tiene masa de 0.200 kg. Cuelga de un dinamómetro y se sumerge por completo en glicerina sin tocar el recipiente. Calcula el empuje y la lectura del dinamómetro.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja peso, empuje, tensión o apoyo según la situación.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Calcula el volumen desplazado y usa la densidad del fluido; después impón equilibrio o compara fuerzas.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"V=(3.14)(2)^2(10)=125.6\"></span> cm<span class=\"math\" data-tex=\"^3=0.0001256\"></span> m<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"E=(1260)(9.81)(0.0001256)=1.55249136\"></span> N. <span class=\"math\" data-tex=\"P=(0.200)(9.81)=1.962\"></span> N; <span class=\"math\" data-tex=\"T=P-E=0.40950864\"></span> N.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"E=1.55249136\\ \\mathrm{N}\"></span>; lectura <span class=\"math\" data-tex=\"=0.40950864\\ \\mathrm{N}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 34 · Empuje y equilibrio", "block": "Empuje y equilibrio", "question": "Un cuerpo pesa 7.848 N en el aire y el dinamómetro indica 6.867 N al sumergirlo completamente en agua. Desprecia el empuje del aire. Calcula el volumen y la densidad del cuerpo.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja peso, empuje, tensión o apoyo según la situación.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Calcula el volumen desplazado y usa la densidad del fluido; después impón equilibrio o compara fuerzas.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"E=7.848-6.867=0.981\"></span> N. <span class=\"math\" data-tex=\"V=E/(1000g)=0.000100\"></span> m<span class=\"math\" data-tex=\"^3=100\"></span> cm<span class=\"math\" data-tex=\"^3\"></span>. <span class=\"math\" data-tex=\"m=7.848/9.81=0.800\"></span> kg. <span class=\"math\" data-tex=\"\\rho=m/V=8000\"></span> kg/m<span class=\"math\" data-tex=\"^3\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"V=100\\ \\mathrm{cm^3}\"></span>; <span class=\"math\" data-tex=\"\\rho=8000\\ \\mathrm{kg/m^3}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 35 · Empuje y equilibrio", "block": "Empuje y equilibrio", "question": "Una esfera hueca cerrada tiene diámetro exterior de 20 cm y masa total de 2 kg. Se mantiene completamente sumergida en agua mediante una cuerda vertical sujeta al fondo. Calcula la tensión de la cuerda.", "steps": [{"title": "Interpretar los datos", "html": "<p>Dibuja peso, empuje, tensión o apoyo según la situación.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Calcula el volumen desplazado y usa la densidad del fluido; después impón equilibrio o compara fuerzas.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>El volumen desplazado es el exterior: <span class=\"math\" data-tex=\"V=(4/3)(3.14)(0.10)^3\"></span> m<span class=\"math\" data-tex=\"^3\"></span>. Sin redondear este volumen, <span class=\"math\" data-tex=\"E=(1000)(9.81)V=41.0712\"></span> N y <span class=\"math\" data-tex=\"P=19.62\"></span> N. La cuerda tira hacia abajo: <span class=\"math\" data-tex=\"T=E-P\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"T=21.4512\\ \\mathrm{N}\"></span></p>"}], "figure": ""}, {"title": "Ejercicio 36 · Presión absoluta", "block": "Presión absoluta", "question": "Un sensor de una llanta tiene un diafragma de 7 cm<span class=\"math\" data-tex=\"^2\"></span>: una cara está en contacto con el aire interior y la otra con la atmósfera. La diferencia de presión produce una fuerza neta de 154 N hacia afuera. La atmósfera local es de 84 kPa. Calcula la presión absoluta interior.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la referencia de cada lectura.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>El efecto de una columna o de F/A es una diferencia de presión. Para p absoluta incluye la atmosférica cuando corresponda.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"A=0.000700\"></span> m<span class=\"math\" data-tex=\"^2\"></span>. La fuerza neta corresponde a la diferencia con la atmósfera: <span class=\"math\" data-tex=\"p_{\\rm man}=154/A=220 000\"></span> Pa <span class=\"math\" data-tex=\"=220\"></span> kPa. Después <span class=\"math\" data-tex=\"p_{\\rm abs}=84+220\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"304\\ \\mathrm{kPa}\"></span> absolutos.</p>"}], "figure": ""}, {"title": "Ejercicio 37 · Presión absoluta", "block": "Presión absoluta", "question": "Un pistón horizontal de área 30 cm<span class=\"math\" data-tex=\"^2\"></span> separa una cámara de una atmósfera de 80 kPa. Para mantenerlo en equilibrio se aplica una fuerza externa de 105 N que tira de él hacia afuera de la cámara. Sin fricción ni otras fuerzas horizontales, calcula la presión absoluta del gas.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la referencia de cada lectura.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>El efecto de una columna o de F/A es una diferencia de presión. Para p absoluta incluye la atmosférica cuando corresponda.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"A=0.00300\"></span> m<span class=\"math\" data-tex=\"^2\"></span>. Hacia afuera actúan el gas y la fuerza aplicada; hacia adentro actúa la atmósfera: <span class=\"math\" data-tex=\"p_{\\rm gas}A+105=p_{\\rm atm}A\"></span>. El déficit es <span class=\"math\" data-tex=\"105/A=35 000\"></span> Pa <span class=\"math\" data-tex=\"=35\"></span> kPa, por lo que <span class=\"math\" data-tex=\"p_{\\rm abs}=80-35\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"45\\ \\mathrm{kPa}\"></span> absolutos.</p>"}], "figure": ""}, {"title": "Ejercicio 38 · Presión absoluta", "block": "Presión absoluta", "question": "Un depósito cilíndrico abierto tiene diámetro interior de 20 cm y contiene 15.7 L de agua. La presión atmosférica local es de 90 kPa. Calcula la presión absoluta en el fondo.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la referencia de cada lectura.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>El efecto de una columna o de F/A es una diferencia de presión. Para p absoluta incluye la atmosférica cuando corresponda.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"V=0.0157\"></span> m<span class=\"math\" data-tex=\"^3\"></span> y <span class=\"math\" data-tex=\"A=(3.14)(0.10)^2=0.0314\"></span> m<span class=\"math\" data-tex=\"^2\"></span>. <span class=\"math\" data-tex=\"h=V/A=0.50\"></span> m. <span class=\"math\" data-tex=\"p_{\\rm fondo,abs}=90+(1000)(9.81)(0.50)/1000\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"94.905\\ \\mathrm{kPa}\"></span> absolutos.</p>"}], "figure": ""}, {"title": "Ejercicio 39 · Presión absoluta", "block": "Presión absoluta", "question": "Un tanque cerrado contiene una capa de agua de 1.20 m y, encima, una capa de aceite de 0.30 m. El gas sobre el aceite tiene presión manométrica de 60 kPa. La atmósfera local es de 85 kPa. Calcula la presión absoluta en el fondo.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la referencia de cada lectura.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>El efecto de una columna o de F/A es una diferencia de presión. Para p absoluta incluye la atmosférica cuando corresponda.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>La presión absoluta del gas es <span class=\"math\" data-tex=\"85+60=145\"></span> kPa. Al bajar se suman ambas columnas: <span class=\"math\" data-tex=\"p_{\\rm fondo,abs}=145+[(1000)(9.81)(1.20)+(860)(9.81)(0.30)]/1000\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"159.30298\\ \\mathrm{kPa}\"></span> absolutos.</p>"}], "figure": ""}, {"title": "Ejercicio 40 · Presión absoluta", "block": "Presión absoluta", "question": "Un gas sostiene un pistón vertical sin fricción de masa 15.7 kg y diámetro 10 cm. La cara superior está expuesta a una atmósfera de 90 kPa. Calcula la presión absoluta del gas en equilibrio; no hay otras cargas.", "steps": [{"title": "Interpretar los datos", "html": "<p>Identifica la referencia de cada lectura.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>El efecto de una columna o de F/A es una diferencia de presión. Para p absoluta incluye la atmosférica cuando corresponda.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"A=(3.14)(0.05)^2=0.00785\"></span> m<span class=\"math\" data-tex=\"^2\"></span>. Del equilibrio, <span class=\"math\" data-tex=\"p_{\\rm gas}A=p_{\\rm atm}A+mg\"></span>. Entonces <span class=\"math\" data-tex=\"p_{\\rm gas}=90+[(15.7)(9.81)/0.00785]/1000=90+19.62\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"109.62\\ \\mathrm{kPa}\"></span> absolutos.</p>"}], "figure": ""}, {"title": "Ejercicio 41 · Presión manométrica y lectura de instrumentos", "block": "Presión manométrica y lectura de instrumentos", "question": "Un sensor compara el gas de un depósito con una cámara de vacío ideal. Sobre un elemento sensible de 5 cm<span class=\"math\" data-tex=\"^2\"></span> la diferencia de presión ejerce una fuerza neta de 125 N. El barómetro local marca 85 kPa. Calcula la presión manométrica del gas.", "steps": [{"title": "Interpretar los datos", "html": "<p>Distingue presión del sistema y presión atmosférica.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa pman = pabs − patm. Si el sistema está abierto, comienza con pman = 0 en la superficie.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>Al referirse al vacío, <span class=\"math\" data-tex=\"p_{\\rm abs}=F/A=125/0.000500=250 000\"></span> Pa <span class=\"math\" data-tex=\"=250\"></span> kPa. Un manómetro descuenta la atmósfera local: <span class=\"math\" data-tex=\"p_{\\rm man}=250-85\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"165\\ \\mathrm{kPa}\"></span> manométricos.</p>"}], "figure": ""}, {"title": "Ejercicio 42 · Presión manométrica y lectura de instrumentos", "block": "Presión manométrica y lectura de instrumentos", "question": "Un sensor referido a un vacío ideal tiene un elemento sensible de 1 cm<span class=\"math\" data-tex=\"^2\"></span> y registra una fuerza neta de 2.80 N debida al gas de una cámara. La atmósfera local es de 80 kPa. Calcula la presión manométrica y la magnitud de la lectura de un vacuómetro.", "steps": [{"title": "Interpretar los datos", "html": "<p>Distingue presión del sistema y presión atmosférica.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa pman = pabs − patm. Si el sistema está abierto, comienza con pman = 0 en la superficie.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"p_{\\rm abs}=2.80/0.000100=28 000\"></span> Pa <span class=\"math\" data-tex=\"=28\"></span> kPa. <span class=\"math\" data-tex=\"p_{\\rm man}=28-80=-52\"></span> kPa. El vacuómetro expresa la magnitud del déficit: <span class=\"math\" data-tex=\"80-28=52\"></span> kPa.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"p_{\\rm man}=-52\\ \\mathrm{kPa}\"></span>; vacío <span class=\"math\" data-tex=\"=52\\ \\mathrm{kPa}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 43 · Presión manométrica y lectura de instrumentos", "block": "Presión manométrica y lectura de instrumentos", "question": "Un depósito rectangular abierto tiene base interior de 20 cm por 25 cm y contiene 12.5 kg de agua. Calcula la presión manométrica en el fondo.", "steps": [{"title": "Interpretar los datos", "html": "<p>Distingue presión del sistema y presión atmosférica.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa pman = pabs − patm. Si el sistema está abierto, comienza con pman = 0 en la superficie.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"V=m/\\rho=12.5/1000=0.0125\"></span> m<span class=\"math\" data-tex=\"^3\"></span> y <span class=\"math\" data-tex=\"A=(0.20)(0.25)=0.0500\"></span> m<span class=\"math\" data-tex=\"^2\"></span>. <span class=\"math\" data-tex=\"h=V/A=0.250\"></span> m. <span class=\"math\" data-tex=\"p_{\\rm man}=1000(9.81)(0.250)\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"2.4525\\ \\mathrm{kPa}\"></span> manométricos.</p>"}], "figure": ""}, {"title": "Ejercicio 44 · Presión manométrica y lectura de instrumentos", "block": "Presión manométrica y lectura de instrumentos", "question": "Un sensor al fondo de un tanque abierto con aceite marca 115.3098 kPa absolutos. La atmósfera local es de 90 kPa. Calcula la presión manométrica en el fondo y la profundidad del aceite.", "steps": [{"title": "Interpretar los datos", "html": "<p>Distingue presión del sistema y presión atmosférica.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa pman = pabs − patm. Si el sistema está abierto, comienza con pman = 0 en la superficie.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p><span class=\"math\" data-tex=\"p_{\\rm man}=115.3098-90=25.3098\"></span> kPa <span class=\"math\" data-tex=\"=25 309.8\"></span> Pa. Como la superficie está abierta, <span class=\"math\" data-tex=\"h=p_{\\rm man}/(\\rho g)=25 309.8/(860\\cdot9.81)\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"p_{\\rm man}=25.3098\\ \\mathrm{kPa}\"></span>; <span class=\"math\" data-tex=\"h=3\\ \\mathrm{m}\"></span>.</p>"}], "figure": ""}, {"title": "Ejercicio 45 · Presión manométrica y lectura de instrumentos", "block": "Presión manométrica y lectura de instrumentos", "question": "En el fondo de un tanque cerrado un sensor registra 160 kPa absolutos. Sobre el fondo hay 1.00 m de agua, encima 0.50 m de aceite y, arriba, un gas. La presión atmosférica local es de 85 kPa. Calcula la presión manométrica del gas.", "steps": [{"title": "Interpretar los datos", "html": "<p>Distingue presión del sistema y presión atmosférica.</p>"}, {"title": "Elegir el modelo físico", "html": "<p>Usa pman = pabs − patm. Si el sistema está abierto, comienza con pman = 0 en la superficie.</p>"}, {"title": "Desarrollo y sustitución", "html": "<p>Al subir desde el fondo se restan las columnas: <span class=\"math\" data-tex=\"p_{\\rm gas,abs}=160-[(1000)(9.81)(1.00)+(860)(9.81)(0.50)]/1000=145.9717\"></span> kPa. Después <span class=\"math\" data-tex=\"p_{\\rm gas,man}=145.9717-85\"></span>.</p>"}, {"title": "Resultado y comprobación", "html": "<p><span class=\"math\" data-tex=\"60.9717\\ \\mathrm{kPa}\"></span> manométricos.</p>"}], "figure": ""}];window.CHAPTERS={"Hidrostática": 0, "Fluidos y equilibrio": 4, "Masa y volumen": 9, "Densidad": 18, "Gravedad específica": 31, "Presión y profundidad": 38, "Presión absoluta y manométrica": 48, "Principio de Pascal": 58, "Manómetro en U": 69, "Empuje y flotación": 83, "Síntesis y práctica": 97};